 const total=file.size,done=state?.status==='done',loaded=done?total:state?.loaded||0,pct=total?Math.round(100*loaded/total):done?100:0;
 const label=done?'اكتمل الرفع':state?.status==='error'?'تعذّر الرفع':state?.status==='uploading'?'جار الرفع…':'جار تهيئة الرفع…';
 return `<div class="submission-upload-status ${done?'is-done':state?.status==='error'?'is-error':''}" data-file-status="${esc(field.id)}" role="status" aria-live="polite"><div class="submission-upload-top"><strong title="${esc(file.name)}">${esc(file.name)}</strong><span>${bytesLabel(total)}</span></div><progress max="100" value="${pct}" aria-label="تقدّم رفع ${esc(file.name)}"></progress><div class="submission-upload-meta"><span class="submission-upload-label">${label}</span><span class="submission-upload-numbers">${bytesLabel(loaded)} / ${bytesLabel(total)} · ${state?.speed?`${bytesLabel(state.speed)}/ث`:'—'}</span></div>${state?.status==='error'?`<div class="submission-upload-error">${esc(state.error||'حاول الرفع مرة أخرى.')}</div><button class="btn small" type="button" data-retry-upload="${esc(field.id)}">إعادة المحاولة</button>`:''}</div>`;
