function updateUploadUi(fieldId){const field=allFields().find(f=>f.id===fieldId),slot=$(`[data-file-status-slot="${CSS.escape(fieldId)}"]`);if(field&&slot){slot.innerHTML=uploadStatusHtml(field);slot.querySelector('[data-retry-upload]')?.addEventListener('click',()=>startFileUpload(fieldId))}}
