 const previous=uploadStates[fieldId];previous?.controller?.abort();delete uploaded[fieldId];const controller=new AbortController(),state={file,status:'preparing',loaded:0,speed:0,error:'',controller,startedAt:performance.now(),lastAt:performance.now(),lastBytes:0};uploadStates[fieldId]=state;updateUploadUi(fieldId);
