   const file=ordered[i].file;if(!file.path)throw new Error(`Missing storage path for ${file.name||file.label||'a file'}.`);
   if(status)status.textContent=`Fetching file ${i+1} of ${ordered.length}…`;
   const blob=await api().downloadSubmissionFile(file.path);
   const name=`${String(i+1).padStart(2,'0')}_${safeArchiveFilename(file.name||file.fieldId||'file')}`;
